const crypto = require('node:crypto');
const { promisify } = require('node:util');
const express = require('express');
const session = require('express-session');

if (!process.env.SESSION_SECRET) throw new Error('SESSION_SECRET is required');

// --- password hashing (stdlib scrypt, stored as "salt:key" hex) ---

const scrypt = promisify(crypto.scrypt);

async function hashPassword(password) {
  const salt = crypto.randomBytes(16);
  const key = await scrypt(password, salt, 64);
  return `${salt.toString('hex')}:${key.toString('hex')}`;
}

async function verifyPassword(password, stored) {
  const [salt, key] = stored.split(':').map((h) => Buffer.from(h, 'hex'));
  return crypto.timingSafeEqual(key, await scrypt(password, salt, key.length));
}

// Verified against when the user doesn't exist, so response time doesn't leak which usernames are real.
const DUMMY_HASH = hashPassword(crypto.randomBytes(16).toString('hex'));

// ponytail: in-memory users, swap for a DB lookup returning { passwordHash }.
const users = new Map(); // username -> { passwordHash }

// --- failed-attempt rate limiting ---

const WINDOW_MS = 15 * 60 * 1000;
const MAX_PER_USER = 5;
const MAX_PER_IP = 20;

// ponytail: in-memory, per-process. Move to Redis when running more than one instance.
const failures = new Map(); // key -> { count, resetAt }

function entry(key) {
  let e = failures.get(key);
  if (!e || e.resetAt <= Date.now()) {
    e = { count: 0, resetAt: Date.now() + WINDOW_MS };
    failures.set(key, e);
  }
  return e;
}

function tooMany(res, e) {
  res.set('Retry-After', Math.ceil((e.resetAt - Date.now()) / 1000));
  return res.status(429).json({ error: 'Too many failed attempts, try again later' });
}

setInterval(() => {
  const now = Date.now();
  for (const [key, e] of failures) if (e.resetAt <= now) failures.delete(key);
}, WINDOW_MS).unref();

// --- app ---

const app = express();
// Behind a reverse proxy, set `app.set('trust proxy', 1)` or req.ip is the proxy's IP
// and secure cookies won't be sent.
app.use(express.json());
app.use(
  session({
    secret: process.env.SESSION_SECRET,
    name: 'sid',
    resave: false,
    saveUninitialized: false,
    // ponytail: default MemoryStore leaks and is per-process. Use connect-redis or similar in production.
    cookie: {
      httpOnly: true,
      sameSite: 'lax',
      secure: process.env.NODE_ENV === 'production',
      maxAge: 8 * 60 * 60 * 1000,
    },
  }),
);

app.post('/login', async (req, res, next) => {
  const { username, password } = req.body ?? {};
  if (
    typeof username !== 'string' || typeof password !== 'string' ||
    !username || !password || username.length > 256 || password.length > 1024
  ) {
    return res.status(400).json({ error: 'username and password are required' });
  }

  // Count the attempt before the async hash check and refund it on success,
  // so a burst of parallel requests can't all slip past the limit.
  const byIp = entry(`ip:${req.ip}`);
  if (byIp.count >= MAX_PER_IP) return tooMany(res, byIp);
  const byUser = entry(`user:${username}`);
  if (byUser.count >= MAX_PER_USER) return tooMany(res, byUser);
  byIp.count++;
  byUser.count++;

  const user = users.get(username);
  const ok = (await verifyPassword(password, user?.passwordHash ?? (await DUMMY_HASH))) && !!user;
  if (!ok) return res.status(401).json({ error: 'Invalid username or password' });

  byIp.count--;
  byUser.count--;
  // New session id on login prevents session fixation.
  req.session.regenerate((err) => {
    if (err) return next(err);
    req.session.username = username;
    res.json({ username });
  });
});

app.post('/logout', (req, res, next) => {
  req.session.destroy((err) => {
    if (err) return next(err);
    res.clearCookie('sid').sendStatus(204);
  });
});

function requireAuth(req, res, next) {
  if (!req.session.username) return res.status(401).json({ error: 'Not logged in' });
  next();
}

app.get('/me', requireAuth, (req, res) => res.json({ username: req.session.username }));

module.exports = { app, users, hashPassword };

if (require.main === module) {
  const port = process.env.PORT || 3000;
  app.listen(port, () => console.log(`listening on ${port}`));
}

process.env.SESSION_SECRET = 'test-secret';
const assert = require('node:assert');
const { app, users, hashPassword } = require('./app');

(async () => {
  users.set('alice', { passwordHash: await hashPassword('correct horse') });
  users.set('bob', { passwordHash: await hashPassword('battery staple') });

  const server = app.listen(0);
  const base = `http://localhost:${server.address().port}`;
  const login = (username, password) =>
    fetch(`${base}/login`, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ username, password }),
    });

  assert.equal((await fetch(`${base}/me`)).status, 401);
  assert.equal((await login('alice', 'wrong')).status, 401);
  assert.equal((await login('nobody', 'wrong')).status, 401);
  assert.equal((await login('alice')).status, 400);

  // success sets a session cookie that authenticates /me, and logout kills it
  const ok = await login('alice', 'correct horse');
  assert.equal(ok.status, 200);
  const cookie = ok.headers.get('set-cookie').split(';')[0];
  const me = await fetch(`${base}/me`, { headers: { cookie } });
  assert.deepEqual(await me.json(), { username: 'alice' });
  assert.equal((await fetch(`${base}/logout`, { method: 'POST', headers: { cookie } })).status, 204);
  assert.equal((await fetch(`${base}/me`, { headers: { cookie } })).status, 401);

  // the success refunded its attempt and the earlier failure counted: 4 more failures, then locked
  for (let i = 0; i < 4; i++) assert.equal((await login('alice', 'wrong')).status, 401);
  const locked = await login('alice', 'correct horse');
  assert.equal(locked.status, 429);
  assert.ok(Number(locked.headers.get('retry-after')) > 0);

  // a parallel burst can't exceed the limit
  const burst = await Promise.all(Array.from({ length: 10 }, () => login('bob', 'wrong')));
  assert.equal(burst.filter((r) => r.status === 401).length, 5);
  assert.equal(burst.filter((r) => r.status === 429).length, 5);

  console.log('ok');
  process.exit(0);
})();

